247	fn complete_option(
248	    arg: &clap_lex::ParsedArg<'_>,
249	    cmd: &clap::Command,
250	    current_dir: Option<&std::path::Path>,
251	) -> Vec<CompletionCandidate> {
252	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
253	    let mut completions = Vec::<CompletionCandidate>::new();
254	    if arg.is_empty() {
255	        completions.extend(longs_and_visible_aliases(cmd));
256	        completions.extend(hidden_longs_aliases(cmd));
257	
258	        let dash_or_arg = if arg.is_empty() {
259	            "-".into()
260	        } else {
261	            arg.to_value_os().to_string_lossy()
262	        };
263	        completions.extend(
264	            shorts_and_visible_aliases(cmd)
265	                .into_iter()
266	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
267	        );
268	    } else if arg.is_stdio() {
269	        // HACK: Assuming knowledge of is_stdio
270	        let dash_or_arg = if arg.is_empty() {
271	            "-".into()
272	        } else {
273	            arg.to_value_os().to_string_lossy()
274	        };
275	        completions.extend(
276	            shorts_and_visible_aliases(cmd)
277	                .into_iter()
278	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
279	        );
280	
281	        completions.extend(longs_and_visible_aliases(cmd));
282	        completions.extend(hidden_longs_aliases(cmd));
283	    } else if arg.is_escape() {
284	        // HACK: Assuming knowledge of is_escape
285	        completions.extend(longs_and_visible_aliases(cmd));
286	        completions.extend(hidden_longs_aliases(cmd));
287	    } else if let Some((flag, value)) = arg.to_long() {
288	        if let Ok(flag) = flag {
289	            if let Some(value) = value {
290	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
291	                    completions.extend(
292	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
293	                            .into_iter()
294	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
295	                    );
296	                }
297	            } else {
298	                completions.extend(
299	                    longs_and_visible_aliases(cmd)
300	                        .into_iter()
301	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
302	                );
303	                completions.extend(
304	                    hidden_longs_aliases(cmd)
305	                        .into_iter()
306	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
307	                );
308	            }
309	        }
310	    } else if let Some(short) = arg.to_short() {
311	        if !short.is_negative_number() {
312	            // Find the first takes_values option.
313	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
314	
315	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
316	            if let Some(opt) = takes_value_opt {
317	                let mut peek_short = short.clone();
318	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
319	                    short.next_flag();
320	                    true
321	                } else {
322	                    false
323	                };
324	
325	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
326	                completions.extend(
327	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
328	                        .into_iter()
329	                        .map(|comp| {
330	                            let sep = if has_equal { "=" } else { "" };
331	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
332	                        }),
333	                );
334	            } else {
335	                completions.extend(
336	                    shorts_and_visible_aliases(cmd)
337	                        .into_iter()
338	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
339	                );
340	            }
341	        }
342	    }
343	    debug!("complete_option: completions={completions:?}");
344	    completions
345	}
