457	fn complete_candidates_str(
458	    value: &str,
459	    mut values: Vec<CompletionCandidate>,
460	) -> Vec<CompletionCandidate> {
461	    debug!("complete_candidates_str: value={value:?}");
462	
463	    values.retain(|comp| comp.get_value().starts_with(value));
464	    values
465	}
