502	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
503	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
504	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
505	    debug!("longs: name={}", p.get_name());
506	
507	    p.get_arguments()
508	        .filter_map(|a| {
509	            a.get_long_and_visible_aliases().map(|longs| {
510	                longs
511	                    .into_iter()
512	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
513	            })
514	        })
515	        .flatten()
516	        .collect()
517	}
518	
519	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
520	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
521	    debug!("longs: name={}", p.get_name());
522	
523	    p.get_arguments()
524	        .filter_map(|a| {
525	            a.get_aliases().map(|longs| {
526	                longs.into_iter().map(|s| {
527	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
528	                })
529	            })
530	        })
531	        .flatten()
532	        .collect()
533	}
