581	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
582	///
583	/// Subcommand `rustup toolchain install` would be converted to
584	/// `("install", "rustup toolchain install")`.
585	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
586	    debug!("subcommands: name={}", p.get_name());
587	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
588	    p.get_subcommands()
589	        .flat_map(|sc| {
590	            sc.get_name_and_visible_aliases()
591	                .into_iter()
592	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
593	                .chain(sc.get_aliases().map(|s| {
594	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
595	                        .hide(true)
596	                }))
597	        })
598	        .collect()
599	}
